def apply(inputs, premises):
    component = inputs['component_id']
    view = inputs['view']
    public = inputs['public_case']
    kernel = inputs['kernel']
    facts = []
    negatives = []
    witnesses = []
    reasons = []
    if type(view) is not dict or view.get('extraction_status') != 'complete':
        return part([], [], [], False, [component + '_unread_or_ambiguous'])
    records = view.get('exact_givens')
    boundaries = view.get('boundary_statements')
    if type(records) is not list or type(boundaries) is not list:
        return part([], [], [], False, ['explicit_legal_channels_unread'])
    support(witnesses, view, public, False)
    citations = {'s151_b':'151(b)','s151_b_applies':'151(b)','s151_c_applies':'151(c)','s152_c_1':'152(c)(1)','s63_f_1_A':'63(f)(1)(A)','s63_f_1_B':'63(f)(1)(B)'}
    seen = set()
    for record in records:
        evidence = checked(record, public, True)
        name = record.get('predicate') if type(record) is dict else None
        args = record.get('arguments') if type(record) is dict else None
        citation = record.get('citation') if type(record) is dict else None
        basis = record.get('basis_text') if type(record) is dict else None
        polarity = record.get('polarity') if type(record) is dict else None
        valid = evidence is not None and valid_given(name, args) and citations.get(name) == citation and polarity in ('positive','negative') and type(basis) is str
        if valid:
            quote = ' '.join(row['quote'].lower() for row in evidence)
            compact = quote.replace('section','').replace('§','').replace(' ','')
            valid = basis.lower() in quote and citation.lower().replace(' ','') in compact
        if valid and is_target_given(kernel, name):
            valid = False
            add(reasons, 'target_legal_query_cannot_be_reasserted_as_fact')
        if not valid:
            add(reasons, 'unsupported_exact_legal_record_discarded')
            continue
        key = (name, tuple(args), polarity)
        if key in seen:
            continue
        seen.add(key)
        for row in evidence:
            add(witnesses, row)
        item = {'predicate': name, 'arguments': list(args)}
        add(negatives if polarity == 'negative' else facts, item)
    for record in boundaries:
        evidence = checked(record, public, True)
        if evidence is None or record.get('kind') not in ('section151_general','section151_d','section151_other','section63_f_general') or record.get('polarity') not in ('positive','negative','descriptive'):
            add(reasons, 'unsupported_legal_boundary_discarded')
            continue
        for row in evidence:
            add(witnesses, row)
    return part(facts, negatives, witnesses, True, reasons)

def apply(inputs, premises):
    component = inputs['component_id']
    view = inputs['view']
    public = inputs['public_case']
    facts = []
    witnesses = []
    reasons = []
    if type(view) is not dict or view.get('extraction_status') != 'complete':
        return part([], [], [], False, [component + '_unread_or_ambiguous'])
    records = view.get('returns')
    if type(records) is not list:
        return part([], [], [], False, ['return_channel_unread'])
    support(witnesses, view, public, False)
    for index, record in enumerate(records):
        evidence = checked(record, public, True)
        persons = record.get('persons') if type(record) is dict else None
        year = record.get('year') if type(record) is dict else None
        year_text = record.get('year_text') if type(record) is dict else None
        kind = record.get('return_type') if type(record) is dict else None
        term = record.get('return_term') if type(record) is dict else None
        basis = record.get('source_basis') if type(record) is dict else None
        expected_basis = 'explicit_joint_return' if kind == 'joint' else 'explicit_separate_return'
        expected_term = 'joint return' if kind == 'joint' else 'separate return'
        valid = evidence is not None and kind in ('joint','separate') and basis == expected_basis and term == expected_term and type(persons) is list and len(persons) > 0 and all(type(x) is str for x in persons)
        valid = valid and ((year is None and year_text is None) or (type(year) is int and type(year_text) is str))
        if valid:
            quote = ' '.join(row['quote'].lower() for row in evidence)
            valid = term in quote and all(person.lower() in quote for person in persons) and (year_text is None or year_text.lower() in quote)
        if not valid:
            add(reasons, 'unsupported_return_record_discarded')
            continue
        for row in evidence:
            add(witnesses, row)
        if kind == 'joint':
            event = 'joint_return_' + str(index)
            put(facts, 'joint_return_', [event])
            for person in persons:
                put(facts, 'agent_', [event, person])
            if type(year) is int:
                put(facts, 'start_', [event, str(year) + '-01-01'])
                put(facts, 'end_', [event, str(year) + '-12-31'])
    return part(facts, [], witnesses, True, reasons)

def general_payment_iso_date(value):
    return type(value) is str and len(value) == 10 and value[4] == '-' and value[7] == '-' and value[:4].isdigit() and value[5:7].isdigit() and value[8:].isdigit()

def apply(inputs, premises):
    component = inputs['component_id']
    view = inputs['view']
    public = inputs['public_case']
    kernel = inputs['kernel']
    facts = []
    witnesses = []
    reasons = []
    if type(view) is not dict or view.get('extraction_status') != 'complete':
        return part([], [], [], False, [component + '_unread_or_ambiguous'])
    payments = view.get('payments')
    boundaries = view.get('annual_income_boundaries')
    if type(payments) is not list or type(boundaries) is not list:
        return part([], [], [], False, ['general_payment_channels_unread'])
    support(witnesses, view, public, False)
    pt = target_payment(kernel)
    st = target_service(kernel)
    pc = 0
    sc = 0
    for index, record in enumerate(payments):
        evidence = checked(record, public, True)
        term = record.get('payment_term') if type(record) is dict else None
        payer = record.get('payer') if type(record) is dict else None
        payer_text = record.get('payer_text') if type(record) is dict else None
        payees = record.get('payees') if type(record) is dict else None
        payee_texts = record.get('payee_texts') if type(record) is dict else None
        amount = record.get('amount') if type(record) is dict else None
        precision = record.get('temporal_precision') if type(record) is dict else None
        date = record.get('payment_date') if type(record) is dict else None
        year = record.get('stated_year') if type(record) is dict else None
        valid = evidence is not None and type(term) is str and (payer is None or type(payer) is str) and ((payer is None and payer_text is None) or type(payer_text) is str)
        valid = valid and type(payees) is list and len(payees) > 0 and all(type(x) is str for x in payees) and type(payee_texts) is list and len(payee_texts) == len(payees) and all(type(x) is str for x in payee_texts)
        valid = valid and (amount is None or type(amount) in (int,float)) and precision in ('full_date','year_only','unstated')
        valid = valid and ((precision == 'full_date' and general_payment_iso_date(date)) or (precision == 'year_only' and date is None and type(year) is int) or (precision == 'unstated' and date is None))
        if valid:
            quote = ' '.join(row['quote'].lower() for row in evidence)
            valid = term.lower() in quote and all(text.lower() in quote for text in payee_texts) and (payer is None or payer_text.lower() in quote)
        if not valid:
            add(reasons, 'unsupported_payment_record_discarded')
            continue
        event = 'general_payment_' + str(index)
        if record.get('is_query_payment') is True:
            pc += 1
            if type(pt) is str:
                event = pt
        for row in evidence:
            add(witnesses, row)
        put(facts, 'payment_', [event])
        if type(payer) is str:
            put(facts, 'agent_', [event, payer])
        for payee in payees:
            put(facts, 'patient_', [event, payee])
        if type(amount) in (int,float):
            put(facts, 'amount_', [event, amount])
        if type(record.get('medium')) is str:
            put(facts, 'means_', [event, record.get('medium')])
        if precision == 'full_date':
            put(facts, 'start_', [event, date])
        linked = record.get('linked_service')
        if type(linked) is dict:
            worker = linked.get('worker')
            employer = linked.get('employer')
            worker_text = linked.get('worker_text')
            employer_text = linked.get('employer_text')
            service_term = linked.get('service_term')
            coherent = all(type(x) is str for x in (worker,employer,worker_text,employer_text,service_term)) and worker in payees and (payer is None or employer == payer)
            coherent = coherent and worker_text.lower() in quote and employer_text.lower() in quote and service_term.lower() in quote
            if not coherent:
                add(reasons, 'unsupported_linked_service_discarded')
            else:
                service = 'general_payment_service_' + str(index)
                if linked.get('is_query_service') is True:
                    sc += 1
                    if type(st) is str:
                        service = st
                put(facts, 'service_', [service])
                put(facts, 'agent_', [service, worker])
                put(facts, 'patient_', [service, employer])
                if type(linked.get('service_kind')) is str:
                    put(facts, 'purpose_', [service, linked.get('service_kind')])
                if type(linked.get('service_venue')) is str:
                    put(facts, 'location_', [service, linked.get('service_venue')])
                if type(linked.get('location')) is str:
                    put(facts, 'location_', [service, linked.get('location')])
                    if type(linked.get('country')) is str:
                        put(facts, 'country_', [linked.get('location'), linked.get('country')])
                if type(linked.get('start_date')) is str:
                    put(facts, 'start_', [service, linked.get('start_date')])
                if type(linked.get('end_date')) is str:
                    put(facts, 'end_', [service, linked.get('end_date')])
                put(facts, 'purpose_', [event, service])
    for record in boundaries:
        evidence = checked(record, public, True)
        if evidence is None or type(record.get('person')) is not str or type(record.get('year')) is not int:
            add(reasons, 'unsupported_annual_income_boundary_discarded')
            continue
        for row in evidence:
            add(witnesses, row)
    if type(pt) is str and len(payments) > 0 and pc != 1:
        add(reasons, 'queried_payment_role_not_uniquely_aligned')
    if type(st) is str and sc > 0 and sc != 1:
        add(reasons, 'queried_service_role_not_uniquely_aligned')
    return part(facts, [], witnesses, True, reasons)

def source_case_core_iso_date(value):
    return type(value) is str and len(value) == 10 and value[4] == '-' and value[7] == '-' and value[:4].isdigit() and value[5:7].isdigit() and value[8:].isdigit()

def apply(inputs, premises):
    component = inputs['component_id']
    view = inputs['view']
    public = inputs['public_case']
    kernel = inputs['kernel']
    facts = []
    negatives = []
    witnesses = []
    reasons = []
    if type(view) is not dict or view.get('extraction_status') != 'complete':
        return part([], [], [], False, [component + '_unread_or_ambiguous'])
    names = ('annual_incomes','exact_givens','kinships','births','residences','marriages','returns','services','payments')
    for name in names:
        if type(view.get(name)) is not list:
            return part([], [], [], False, ['source_case_core_channel_unread_' + name])
    support(witnesses, view, public, False)
    for index, record in enumerate(view.get('annual_incomes')):
        if not support(witnesses, record, public, True) or type(record.get('person')) is not str or type(record.get('year')) is not int or type(record.get('amount')) not in (int,float):
            add(reasons, 'unsupported_annual_income_discarded')
            continue
        event = 'core_income_' + str(index)
        put(facts, 'income_', [event])
        put(facts, 'agent_', [event, record.get('person')])
        put(facts, 'amount_', [event, record.get('amount')])
        put(facts, 'start_', [event, str(record.get('year')) + '-01-01'])
        put(facts, 'end_', [event, str(record.get('year')) + '-12-31'])
    citations = {'s151_b':'151(b)','s151_b_applies':'151(b)','s151_c_applies':'151(c)','s152_c_1':'152(c)(1)','s63_f_1_A':'63(f)(1)(A)','s63_f_1_B':'63(f)(1)(B)'}
    for record in view.get('exact_givens'):
        evidence = checked(record, public, True)
        name = record.get('predicate') if type(record) is dict else None
        args = record.get('arguments') if type(record) is dict else None
        citation = record.get('citation') if type(record) is dict else None
        basis = record.get('basis_text') if type(record) is dict else None
        polarity = record.get('polarity') if type(record) is dict else None
        valid = evidence is not None and valid_given(name, args) and citations.get(name) == citation and type(basis) is str and polarity in ('positive','negative') and not is_target_given(kernel, name)
        if valid:
            quote = ' '.join(row['quote'].lower() for row in evidence)
            valid = basis.lower() in quote and citation.lower().replace(' ','') in quote.replace('section','').replace('§','').replace(' ','')
        if not valid:
            add(reasons, 'unsupported_exact_given_discarded')
            continue
        for row in evidence:
            add(witnesses, row)
        item = {'predicate': name, 'arguments': list(args)}
        add(negatives if polarity == 'negative' else facts, item)
    for index, record in enumerate(view.get('kinships')):
        if not support(witnesses, record, public, True):
            add(reasons, 'unsupported_kinship_discarded')
            continue
        relation = record.get('relation')
        related = record.get('related_person')
        reference = record.get('reference_person')
        if relation not in ('son','daughter','father','mother','brother','sister','sibling') or type(related) is not str or type(reference) is not str:
            add(reasons, 'unsupported_kinship_discarded')
            continue
        event = 'core_kinship_' + str(index)
        put(facts, relation + '_', [event])
        put(facts, 'agent_', [event, related])
        put(facts, 'patient_', [event, reference])
        if type(record.get('start_date')) is str:
            put(facts, 'start_', [event, record.get('start_date')])
        if type(record.get('end_date')) is str:
            put(facts, 'end_', [event, record.get('end_date')])
    for index, record in enumerate(view.get('births')):
        if not support(witnesses, record, public, True) or type(record.get('person')) is not str or type(record.get('date')) is not str:
            add(reasons, 'unsupported_birth_discarded')
            continue
        event = 'core_birth_' + str(index)
        put(facts, 'birth_', [event])
        put(facts, 'agent_', [event, record.get('person')])
        put(facts, 'start_', [event, record.get('date')])
    for index, record in enumerate(view.get('residences')):
        persons = record.get('persons') if type(record) is dict else None
        if not support(witnesses, record, public, True) or type(persons) is not list or len(persons) == 0 or not all(type(x) is str for x in persons) or type(record.get('location')) is not str:
            add(reasons, 'unsupported_residence_discarded')
            continue
        for position, person in enumerate(persons):
            event = 'core_residence_' + str(index) + '_' + str(position)
            put(facts, 'residence_', [event])
            put(facts, 'agent_', [event, person])
            put(facts, 'patient_', [event, record.get('location')])
            if type(record.get('start_date')) is str:
                put(facts, 'start_', [event, record.get('start_date')])
            if type(record.get('end_date')) is str:
                put(facts, 'end_', [event, record.get('end_date')])
    for index, record in enumerate(view.get('marriages')):
        persons = record.get('persons') if type(record) is dict else None
        if not support(witnesses, record, public, True) or type(persons) is not list or len(persons) != 2 or not all(type(x) is str for x in persons):
            add(reasons, 'unsupported_marriage_discarded')
            continue
        event = 'core_marriage_' + str(index)
        put(facts, 'marriage_', [event])
        put(facts, 'agent_', [event, persons[0]])
        put(facts, 'agent_', [event, persons[1]])
        if type(record.get('start_date')) is str:
            put(facts, 'start_', [event, record.get('start_date')])
        if type(record.get('end_date')) is str:
            put(facts, 'end_', [event, record.get('end_date')])
    for index, record in enumerate(view.get('returns')):
        persons = record.get('persons') if type(record) is dict else None
        kind = record.get('return_type') if type(record) is dict else None
        if not support(witnesses, record, public, True) or type(persons) is not list or len(persons) == 0 or not all(type(x) is str for x in persons) or kind not in ('joint','separate'):
            add(reasons, 'unsupported_return_discarded')
            continue
        if kind == 'joint':
            event = 'core_joint_return_' + str(index)
            put(facts, 'joint_return_', [event])
            for person in persons:
                put(facts, 'agent_', [event, person])
            if type(record.get('year')) is int:
                put(facts, 'start_', [event, str(record.get('year')) + '-01-01'])
                put(facts, 'end_', [event, str(record.get('year')) + '-12-31'])
    service_ids = {}
    st = target_service(kernel)
    sc = 0
    for index, record in enumerate(view.get('services')):
        local_id = record.get('local_id') if type(record) is dict else None
        if not support(witnesses, record, public, True) or type(local_id) is not str or local_id in service_ids or type(record.get('worker')) is not str or type(record.get('employer')) is not str:
            add(reasons, 'unsupported_service_discarded')
            continue
        event = 'core_service_' + str(index)
        if record.get('is_query_service') is True:
            sc += 1
            if type(st) is str:
                event = st
        service_ids[local_id] = event
        put(facts, 'service_', [event])
        put(facts, 'agent_', [event, record.get('worker')])
        put(facts, 'patient_', [event, record.get('employer')])
        if type(record.get('service_kind')) is str:
            put(facts, 'purpose_', [event, record.get('service_kind')])
        if type(record.get('service_venue')) is str:
            put(facts, 'location_', [event, record.get('service_venue')])
        if type(record.get('location')) is str:
            put(facts, 'location_', [event, record.get('location')])
            if type(record.get('country')) is str:
                put(facts, 'country_', [record.get('location'), record.get('country')])
        if type(record.get('start_date')) is str:
            put(facts, 'start_', [event, record.get('start_date')])
        if type(record.get('end_date')) is str:
            put(facts, 'end_', [event, record.get('end_date')])
    pt = target_payment(kernel)
    pc = 0
    for index, record in enumerate(view.get('payments')):
        payees = record.get('payees') if type(record) is dict else None
        precision = record.get('temporal_precision') if type(record) is dict else None
        date = record.get('payment_date') if type(record) is dict else None
        valid = support(witnesses, record, public, True) and type(payees) is list and len(payees) > 0 and all(type(x) is str for x in payees) and (record.get('payer') is None or type(record.get('payer')) is str)
        valid = valid and ((precision == 'full_date' and source_case_core_iso_date(date)) or (precision == 'year_only' and date is None and type(record.get('stated_year')) is int) or (precision == 'unstated' and date is None))
        if not valid:
            add(reasons, 'unsupported_payment_discarded')
            continue
        linked = record.get('service_local_id')
        if linked is not None and linked not in service_ids:
            add(reasons, 'payment_links_unknown_service')
            continue
        event = 'core_payment_' + str(index)
        if record.get('is_query_payment') is True:
            pc += 1
            if type(pt) is str:
                event = pt
        put(facts, 'payment_', [event])
        if type(record.get('payer')) is str:
            put(facts, 'agent_', [event, record.get('payer')])
        for payee in payees:
            put(facts, 'patient_', [event, payee])
        if type(record.get('amount')) in (int,float):
            put(facts, 'amount_', [event, record.get('amount')])
        if type(record.get('medium')) is str:
            put(facts, 'means_', [event, record.get('medium')])
        if precision == 'full_date':
            put(facts, 'start_', [event, date])
        if type(linked) is str:
            put(facts, 'purpose_', [event, service_ids[linked]])
    if type(st) is str and len(view.get('services')) > 0 and sc != 1:
        add(reasons, 'queried_service_role_not_uniquely_aligned')
    if type(pt) is str and len(view.get('payments')) > 0 and pc != 1:
        add(reasons, 'queried_payment_role_not_uniquely_aligned')
    return part(facts, negatives, witnesses, True, reasons)
